<template><div class="page-heading"><div><h1>工作计划</h1><p>把模糊的目标拆成有起止、有优先级的推进路径。</p></div><el-button type="primary" @click="openCreate">+ 新建计划</el-button></div><div class="toolbar"><el-date-picker v-model="month" type="month" value-format="YYYY-MM" @change="load" /><span class="muted-text">月度日历视图 · 共 {{ rows.length }} 项计划</span></div><div class="desktop-table table-card"><el-table :data="rows" stripe><el-table-column prop="title" label="计划" min-width="240" /><el-table-column label="时间范围" width="220"><template #default="s">{{ s.row.start_date }} → {{ s.row.end_date }}</template></el-table-column><el-table-column label="优先级" width="110"><template #default="s"><span :class="['status-tag', s.row.priority === 'high' ? 'high' : '']">{{ priorityMap[s.row.priority] }}</span></template></el-table-column><el-table-column label="状态" width="120"><template #default="s"><el-tag :type="s.row.status === 'done' ? 'success' : 'warning'" size="small">{{ s.row.status === 'done' ? '已完成' : '进行中' }}</el-tag></template></el-table-column><el-table-column label="操作" width="140"><template #default="s"><el-button link type="primary" @click="edit(s.row)">编辑</el-button><el-button link type="danger" @click="remove(s.row.id)">删除</el-button></template></el-table-column></el-table><el-empty v-if="!rows.length" description="这个月还没有计划" /></div><div class="mobile-card-list"><article v-for="row in rows" :key="row.id" class="mobile-plan-card mobile-content-card"><div class="mobile-card-meta"><span>{{ row.start_date }} → {{ row.end_date }}</span><span :class="['status-tag', row.priority === 'high' ? 'high' : '']">{{ priorityMap[row.priority] }}</span></div><h3>{{ row.title }}</h3><p v-if="row.description" class="mobile-card-description">{{ row.description }}</p><div class="mobile-card-footer"><el-tag :type="row.status === 'done' ? 'success' : 'warning'" size="small">{{ row.status === 'done' ? '已完成' : '进行中' }}</el-tag><div class="mobile-card-actions"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link type="danger" @click="remove(row.id)">删除</el-button></div></div></article><el-empty v-if="!rows.length" description="这个月还没有计划" /></div><el-dialog v-model="dialog" :title="editing?'编辑计划':'新建计划'" width="560px"><el-form :model="form" label-width="75px"><el-form-item label="计划名称"><el-input v-model="form.title" /></el-form-item><el-form-item label="描述"><el-input v-model="form.description" type="textarea" :rows="3" /></el-form-item><div class="two-col"><el-form-item label="开始日期"><el-date-picker v-model="form.start_date" value-format="YYYY-MM-DD" style="width:100%" /></el-form-item><el-form-item label="结束日期"><el-date-picker v-model="form.end_date" value-format="YYYY-MM-DD" style="width:100%" /></el-form-item></div><div class="two-col"><el-form-item label="优先级"><el-select v-model="form.priority" style="width:100%"><el-option label="高优先级" value="high"/><el-option label="中优先级" value="medium"/><el-option label="低优先级" value="low"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="form.status" style="width:100%"><el-option label="待开始" value="pending"/><el-option label="进行中" value="doing"/><el-option label="已完成" value="done"/></el-select></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></template>
<script setup>import { reactive,ref,onMounted } from 'vue';import {ElMessage} from 'element-plus';import {api} from '../api/http';const rows=ref([]),month=ref(new Date().toISOString().slice(0,7)),dialog=ref(false),editing=ref(null),priorityMap={high:'高',medium:'中',low:'低'};const form=reactive({title:'',description:'',start_date:new Date().toISOString().slice(0,10),end_date:new Date().toISOString().slice(0,10),priority:'medium',status:'pending'});async function load(){rows.value=(await api.plans({month:month.value})).data}function openCreate(){editing.value=null;Object.assign(form,{title:'',description:'',start_date:new Date().toISOString().slice(0,10),end_date:new Date().toISOString().slice(0,10),priority:'medium',status:'pending'});dialog.value=true}function edit(r){editing.value=r.id;Object.assign(form,r);dialog.value=true}async function save(){if(!form.title)return ElMessage.warning('请填写计划名称');editing.value?await api.updatePlan(editing.value,form):await api.plan(form);dialog.value=false;ElMessage.success('计划已保存');load()}async function remove(id){await api.deletePlan(id);load()}onMounted(load)</script>
